'use strict';

/**
* Multiply each element in an input one-dimensional single-precision complex floating-point ndarray by a scalar constant and assign the results to elements in a one-dimensional single-precision complex floating-point output ndarray.
*
* @module @stdlib/blas-ext-base-ndarray-cwax
*
* @example
* var Complex64Vector = require( '@stdlib/ndarray-vector-complex64' );
* var Complex64 = require( '@stdlib/complex-float32-ctor' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var cwax = require( '@stdlib/blas-ext-base-ndarray-cwax' );
*
* var x = new Complex64Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
* var w = new Complex64Vector( 2 );
*
* var alpha = scalar2ndarray( new Complex64( 5.0, 0.0 ), {
*     'dtype': 'complex64'
* });
*
* var out = cwax( [ x, w, alpha ] );
* // returns <ndarray>[ <Complex64>[ -10.0, 5.0 ], <Complex64>[ 15.0, -25.0 ] ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
